/**
 * The recovery matrix: for each treatment and each lasting effect, whether recovery is usual, partial or
 * unlikely, over what timescale, in what proportion, and from which source.
 *
 * The question people ask when treatment ends is "will this come back", and it is answered one organ at a time
 * in papers a patient will never see. This file puts the answers in one place. It is side data, like
 * src/data/survivorship.ts (which gives the screening test for each late effect) and src/data/hair-loss.ts;
 * `drugIds`, `relatedIds` and `entityIds` are ids in this corpus and are validated at build by /live/recovery/
 * and by src/data/recovery-matrix.test.ts.
 *
 * Rules this file is held to:
 *  - A cell exists only where a source states something about recovery. No cell is written from first principles.
 *  - `proportion` is copied from the source with the cohort it came from. A figure without a cohort is not a figure.
 *  - `quote` is a verbatim fragment of the abstract, label or guideline the cell rests on, and
 *    src/data/recovery-matrix.test.ts holds the shape of every cell. Quotes were checked against the Europe PMC
 *    abstract text at the time of writing, by exact string match, not by recollection.
 *  - A missing cell means no source was found, never that nothing happens. Cells with outlook "unknown" are the
 *    questions readers ask most often where the literature does not answer them, written out rather than left blank.
 *  - British spelling throughout, and a quotation is never altered.
 *
 * The matrix is deliberately sparse and the page says what share of it is filled, because a grid that looks
 * complete and is half guessed is worse than no grid.
 */

export type Source = { label: string; url: string };

/** Whether the function comes back: the four answers a source can support. */
export type RecoveryOutlook = "usual" | "partial" | "unlikely" | "unknown";

export const OUTLOOK_META: Record<RecoveryOutlook, { label: string; blurb: string; chip: string; dot: string }> = {
  usual: { label: "Usually comes back", blurb: "Most people return to about where they started, in the timescale the source gives.", chip: "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300 border border-emerald-500/30", dot: "bg-emerald-500" },
  partial: { label: "Partly comes back", blurb: "Improvement is usual and complete recovery is not; a minority are left with something lasting.", chip: "bg-amber-500/15 text-amber-700 dark:text-amber-300 border border-amber-500/30", dot: "bg-amber-500" },
  unlikely: { label: "Does not usually come back", blurb: "The damage is permanent in most people who get it, and the lever is prevention or replacement rather than recovery.", chip: "bg-rose-500/15 text-rose-700 dark:text-rose-300 border border-rose-500/30", dot: "bg-rose-500" },
  unknown: { label: "Not established", blurb: "The effect is recognised and no study found reports how often it recovers. Named here rather than left blank.", chip: "bg-foreground/10 text-muted border border-border", dot: "bg-foreground/30" },
};

/** One lasting effect: a column of the matrix. */
export type RecoveryEffect = {
  id: string;
  label: string;
  /** Short label for the grid header. */
  short: string;
  /** One sentence for a reader meeting the term for the first time. */
  plain: string;
  /** Records in the corpus that cover this effect. */
  entityIds: string[];
};

/** One treatment or class: a row of the matrix. */
export type RecoveryTreatment = {
  id: string;
  label: string;
  group: "Chemotherapy" | "Antibodies and targeted medicines" | "Immunotherapy and cell therapy" | "Hormone therapy" | "Radiotherapy" | "Surgery";
  /** One sentence on what this is, for a reader who has only been told the brand name. */
  plain: string;
  drugIds: string[];
  relatedIds: string[];
  /** The matching entry in src/data/survivorship.ts, where one exists, so the two pages agree on what a class is. */
  survivorshipId?: string;
};

/** One cell: what happens to one effect after one treatment. */
export type RecoveryCell = {
  treatment: string;
  effect: string;
  outlook: RecoveryOutlook;
  /** The answer in one sentence, including the honest limit. */
  line: string;
  /** How long, in the source's own terms. */
  timescale?: string;
  /** The figure the source gives and the cohort it came from. Omitted where the source gives neither. */
  proportion?: { figure: string; cohort: string };
  source: Source;
  also?: Source;
  /** Verbatim fragment of the source the cell rests on. */
  quote?: string;
  /** Drugs this cell is specifically about, where it is narrower than the row. */
  drugIds?: string[];
  /** What was searched, for cells whose outlook is "unknown". */
  searched?: string;
};

/** A published cumulative dose above which the effect becomes much more likely. The number lives here, not in prose. */
export type RecoveryThreshold = {
  id: string;
  treatment: string;
  effect: string;
  /** The threshold in the source's own terms. */
  threshold: string;
  cohort: string;
  source: Source;
  quote?: string;
};

