    proportion: { figure: "hot flushes in 59% at 24 months, up from 6% before surgery; 54% of hormone therapy users and 88% of non-users still had them", cohort: "104 premenopausal women having risk-reducing surgery, with 102 age-matched comparators (WHAM study)" },
    source: { label: "WHAM study, 24 months after premenopausal risk-reducing salpingo-oophorectomy, Gynecologic Oncology 2024", url: "https://doi.org/10.1016/j.ygyno.2024.10.007" },
