    source: { label: "Impact of risk-reducing bilateral salpingo-oophorectomy on sexual function: systematic review and meta-analysis, European Journal of Obstetrics and Gynecology and Reproductive Biology 2021", url: "https://doi.org/10.1016/j.ejogrb.2021.08.001" },
