    source: { label: "The Platinum Study, EClinicalMedicine 2026", url: "https://doi.org/10.1016/j.eclinm.2026.103841" },
    also: { label: "Progressive sensorineural hearing loss following cisplatin chemotherapy, Pharmaceuticals 2026", url: "https://doi.org/10.3390/ph19050779" },
