    proportion: { figure: "69 of 101 (68.3%) had electrophysiological evidence of neuropathy, and 16 (15.8%) had both clinical and electrophysiological neuropathy", cohort: "101 Malaysian survivors of childhood acute lymphoblastic leukaemia aged 4 to 18" },
