// =============================================================================
// THE ENDOCRINE EXCEPTION
// =============================================================================
export type EndocrineRow = {
  id: string;
  gland: string;
  what: string;
  outlook: RecoveryOutlook;
  proportion?: { figure: string; cohort: string };
  source: Source;
  quote?: string;
};

/**
 * Checkpoint inhibitors are the one treatment where the usual order is reversed: the inflammation of a visceral
 * organ mostly settles, and the damage to a hormone gland mostly does not. It has its own section on the page
 * because it is the thing patients are least often told at the time of consent.
 */
export const ENDOCRINE_EXCEPTION: { title: string; intro: string; outro: string; rows: EndocrineRow[] } = {
  title: "The endocrine exception",
  intro: "Nearly everything written about immunotherapy side effects says they are manageable and reversible, and for the liver, the bowel, the lungs and the skin that is broadly true. The hormone glands are the exception, and the people who follow patients after treatment ends have measured it: in 387 people given a year of anti-PD-1 after melanoma surgery, 83 per cent of the hormone problems were still there three months after the drug stopped, while colitis persisted in 6 of 44 cases and most of those cleared in the end. A gland that has been destroyed does not grow back. What follows is what each gland does, and what the follow-up cohorts found.",
  outro: "None of this is an argument against checkpoint inhibitors, which cure people who would once have died. It is an argument for being told at the start, for a hormone blood test at the first hint of exhaustion, nausea or dizziness, and for nobody being left to work out years later that the tiredness they have had since treatment is an untreated hormone deficiency. Replacement is cheap, lifelong and effective: the harm is in the delay, not in the diagnosis.",
  rows: [
    { id: "rejuv-recovery-endocrine-pituitary", gland: "Pituitary (hypophysitis)",
      what: "Inflammation of the gland that instructs the others. It typically appears about three months in, and the first sign is often headache or a flat exhaustion that is put down to the cancer.",
      outlook: "unlikely",
      proportion: { figure: "none of 22 recovered the adrenal axis; the thyroid axis recovered in 33% and the gonadal axis in 67%", cohort: "22 patients with checkpoint-induced hypophysitis at a tertiary endocrine and immunotherapy clinic" },
      source: { label: "Checkpoint inhibitor hypophysitis in a tertiary centre, Clinical Endocrinology 2026", url: "https://doi.org/10.1111/cen.70137" },
      quote: "None recovered SAI during follow-up, whilst recovery of SH and SHG was noted in 33% and 67%, respectively." },
    { id: "rejuv-recovery-endocrine-thyroid", gland: "Thyroid (thyroiditis)",
      what: "A brief overactive phase, often missed, followed by an underactive gland. It is the commonest hormonal effect of these drugs and the easiest to replace.",
      outlook: "unlikely",
      proportion: { figure: "2 of 103 regained their own thyroid function; 64 reached normal levels on levothyroxine", cohort: "103 patients with checkpoint-associated thyroiditis at an academic centre" },
      source: { label: "Levothyroxine dosing in checkpoint-associated hypothyroidism, Thyroid 2022", url: "https://doi.org/10.1089/thy.2021.0685" },
      quote: "Sixty-six of the 103 patients achieved euthyroid state; 2 with intrinsic thyroid gland function recovery and 64 on LT4." },
    { id: "rejuv-recovery-endocrine-adrenal", gland: "Adrenal glands",
      what: "Loss of cortisol, either from the pituitary above or from the adrenal glands themselves. Untreated it can be fatal in an illness or an operation, which is why it is the one worth knowing about before it happens.",
      outlook: "unlikely",
      proportion: { figure: "of 93 people whose immune side effects were still present at last follow-up, 16 were on replacement steroids for hypophysitis or adrenal insufficiency", cohort: "318 patients given adjuvant anti-PD-1 for resected melanoma at six centres in the United States and Australia, median follow-up 1,057 days" },
      source: { label: "Extended follow-up of chronic immune-related adverse events, JAMA Network Open 2023", url: "https://doi.org/10.1001/jamanetworkopen.2023.27145" },
      quote: "24 (25.8%) were using therapeutic systemic steroids (16 [67%] of whom were on replacement steroids for hypophysitis (8 [50.0%]) and adrenal insufficiency (8 [50.0%])" },
    { id: "rejuv-recovery-endocrine-pancreas", gland: "Insulin-making cells of the pancreas",
      what: "A sudden diabetes, often presenting as a diabetic emergency rather than as a gradual rise in blood sugar. The cells that make insulin are destroyed, not suppressed.",
      outlook: "unlikely",
      proportion: { figure: "all 34 remained insulin-dependent at the end of follow-up", cohort: "CANDIED, five Canadian cancer centres, patients on anti-PD-1 or anti-PD-L1 based therapy, onset at a median 2.4 months" },
      source: { label: "CANDIED, checkpoint-induced insulin-dependent diabetes, Cancers 2021", url: "https://doi.org/10.3390/cancers14010089" },
      quote: "All patients remained insulin-dependent at the end of follow-up." },
    { id: "rejuv-recovery-endocrine-contrast", gland: "For contrast: the bowel",
      what: "Colitis is the immune side effect people are warned about most, and it is the one that behaves the way the consent conversation describes: it settles, and the few cases that drag on mostly clear in the end.",
      outlook: "usual",
      proportion: { figure: "colitis became chronic in 6 of 44 cases, and 4 of those 6 later resolved, against 73 of 88 hormone problems becoming chronic", cohort: "387 patients given adjuvant anti-PD-1 for stage III to IV melanoma at eight academic centres" },
      source: { label: "Chronic immune-related adverse events after adjuvant anti-PD-1, JAMA Oncology 2021", url: "https://doi.org/10.1001/jamaoncol.2021.0051" },
      quote: "Endocrinopathies (73 of 88; 83.0%), arthritis (22 of 45; 48.9%), xerostomia (9 of 17; 52.9%), neurotoxicities (11 of 15; 73.3%), and ocular events (5 of 8; 62.5%) were particularly likely to become chronic." },
  ],
};

/**
 * How much of the grid is filled, measured rather than asserted. The page states this in its first paragraph,
 * because a reader should know how much of this is unknown before they read any of it.
 *
 * `sourced` counts answers, `squares` counts the treatment-and-effect squares at least one of them fills: a pair
 * can carry more than one answer where the literature separates, for example, the acute and the lasting form of
 * oxaliplatin nerve damage. `pct` is squares over the whole grid, which is the conservative reading: some pairs
 * in the grid do not arise at all, so the true share of answerable questions that are answered is higher.
 */
export function recoveryFill() {
  const grid = RECOVERY_TREATMENTS.length * RECOVERY_EFFECTS.length;
  const answered = RECOVERY_CELLS.filter((c) => c.outlook !== "unknown");
  const squares = new Set(answered.map((c) => `${c.treatment}|${c.effect}`)).size;
  return {
    grid,
    cells: RECOVERY_CELLS.length,
    sourced: answered.length,
    squares,
    withProportion: RECOVERY_CELLS.filter((c) => c.proportion).length,
    named: RECOVERY_CELLS.filter((c) => c.outlook === "unknown").length,
    thresholds: RECOVERY_THRESHOLDS.length,
    treatments: RECOVERY_TREATMENTS.length,
    effects: RECOVERY_EFFECTS.length,
    pct: Math.round((squares / grid) * 1000) / 10,
  };
}

/** Every cell for one treatment, in column order. */
export const cellsFor = (treatment: string): RecoveryCell[] =>
  RECOVERY_EFFECTS.flatMap((e) => RECOVERY_CELLS.filter((c) => c.treatment === treatment && c.effect === e.id));

/** Every cell that applies to one medicine, through the row it belongs to or through a cell of its own. */
export const cellsForDrug = (drugId: string): RecoveryCell[] => {
  const rows = RECOVERY_TREATMENTS.filter((t) => t.drugIds.includes(drugId)).map((t) => t.id);
  return RECOVERY_CELLS.filter((c) => (c.drugIds ? c.drugIds.includes(drugId) : rows.includes(c.treatment) && !c.drugIds));
};

/** The medicines in the corpus that gain a recovery line from this file. */
export const recoveryDrugIds = (): string[] =>
  [...new Set([...RECOVERY_TREATMENTS.flatMap((t) => t.drugIds), ...RECOVERY_CELLS.flatMap((c) => c.drugIds ?? [])])].sort();
